def deformation {n : ℕ} (h : FinitePoint n → Pair) (c : FinitePoint n)
    {v : Pair} (p : Path (h c) v) (q : ℝ × FinitePoint n) : Pair :=
  h (contraction c (contractionTime q.1) q.2) + p.extend (constantTime q.1) - h c

